(function(){try{var e=typeof window<`u`?window:typeof global<`u`?global:typeof globalThis<`u`?globalThis:typeof self<`u`?self:{};e.SENTRY_RELEASE={id:`f99fcf9f0a844cc9bd13fdc8e5782b84`};var t=new e.Error().stack;t&&(e._sentryDebugIds=e._sentryDebugIds||{},e._sentryDebugIds[t]=`90cd5661-69d7-44eb-9b10-308ffabf0dc7`,e._sentryDebugIdIdentifier=`sentry-dbid-90cd5661-69d7-44eb-9b10-308ffabf0dc7`)}catch{}})();import{$t as e,St as t,Tn as n,Tt as r,bt as i,c as a,d as o,en as s,tn as c,wn as l}from"./F_ixKBiO.js";import"./B1sc9Zdx.js";import"./Bb2deiU3.js";import{t as u}from"./JPsrybyr.js";import{t as d}from"./DeWGVqas2.js";import{t as f}from"./CdZDxCfO2.js";var p={title:`How we used evals and inference-time compute scaling to generate beautiful QR codes that actually work`,description:`There's only one playbook for improving generative applications. Read about it here.`,authors:[{name:`Charles Frye`,avatarUrl:`https://modal-cdn.com/charles-frye.jpg`,jobTitle:`Developer Advocate`,twitterHandle:`charles_irl`},{name:`Will Shainin`,avatarUrl:`https://modal-cdn.com/will-shainin.jpg`,jobTitle:`ML Engineer`,twitterHandle:`Will_Modal`},{name:`Erik Dunteman`,avatarUrl:`https://modal-cdn.com/erik-dunteman.jpg`,jobTitle:`Founder, pig.dev`,twitterHandle:`erikdunteman`}],date:`2025-07-02T09:00:00.000Z`,length:`15 minute read`,category:`Research`,published:!0,layout:`blog`,toc:[{depth:2,value:`Generative models always start with a cool demo, like QR codes that look beautiful.`,id:`generative-models-always-start-with-a-cool-demo-like-qr-codes-that-look-beautiful`},{depth:2,value:`Then comes the disappointment, like QR codes that don’t scan.`,id:`then-comes-the-disappointment-like-qr-codes-that-dont-scan`},{depth:2,value:`We solved this quality gap by developing good evals, following the standard ML engineering playbook: collect human judgments, align to them, then scale.`,id:`we-solved-this-quality-gap-by-developing-good-evals-following-the-standard-ml-engineering-playbook-collect-human-judgments-align-to-them-then-scale`},{depth:2,value:`The final piece (not the first) is scaling up offline compute to select system parameters.`,id:`the-final-piece-not-the-first-is-scaling-up-offline-compute-to-select-system-parameters`},{depth:2,value:`Our evals were good enough to move them to production — so we could solve all of our problems by scaling compute!`,id:`our-evals-were-good-enough-to-move-them-to-production--so-we-could-solve-all-of-our-problems-by-scaling-compute`},{depth:2,value:`If you’d like to go “beyond the demo” and build robust applications of generative models, try Modal.`,id:`if-youd-like-to-go-beyond-the-demo-and-build-robust-applications-of-generative-models-try-modal`}],rawContent:`Two techniques dominate discussion of the engineering of language model applications and artificial intelligence: [evals](https://x.com/leonardtang_/status/1919147635794977207) and [inference-time compute scaling](/blog/llama-human-eval). These techniques are general, far beyond topics du jour like RAG chatbots and code completion and AI boyfriends. In fact, they are fundamental to any application of foundation generative models.

In this blog post, we’ll walk through how we used evals and inference-time scaling to improve the quality for our implementation of one of the first viral applications of image generation models: encoding QR data inside a generated image (aka _QArt codes_).

Here are some samples from our system, without any per-prompt cherry-picking:

<div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; max-width: 50%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-code-green-cubes.webp" alt="Neon green cubes, rendered in blender…" />
  <img src="https://modal-cdn.com/blog/images/qart-code-jungle.webp" alt="A dense jungle scene filled with towering trees, intertwining vines, and an abundance of foliage…" />
  <img src="https://modal-cdn.com/blog/images/qart-code-penguins.webp" alt="Penguins have a picnic on the Savannah…" />
  <img src="https://modal-cdn.com/blog/images/qart-code-graffiti.webp" alt="A close-up view of a vibrant graffiti-covered urban wall…" />
</div>

We were able to

- **boost QR code scan rate** to our **service-level objective of ninety-five percent**
- while **improving aesthetic quality**
- and returning codes to users **in under 20s**, p95.

We use codes like these in all the places we might use QR codes — like guerrilla marketing and credit giveaways.

You can try the system for yourself at [https://qart.codes](https://qart.codes), check out the code [here](https://github.com/charlesfrye/qart-codes), or read on for more about how we did it — and learn some ideas for engineering your own generative model applications.

## Generative models always start with a cool demo, like QR codes that look beautiful.

The same basic story has played itself out over and over again in this early era of “generative AI”. A new foundation model or technique for some domain trends on social media and there’s a gold rush as a million hackers simultaneously build zero-to-one proofs of concept in a day. Whether it’s making pictures of cats or booking a flight, it works well enough to cut a demo video and maybe snag some of the least intelligent VC money.

One of the first instances of this pattern kicked off on June 5, 2023, when Reddit user nhciao [posted](https://reddit.com/r/StableDiffusion/comments/141hg9x/controlnet_for_qr_code/) “ControlNet for QR Code” on the Stable Diffusion subreddit, demonstrating that diffusion models with ControlNet steering could create images that were also QR codes.

<div style="max-width: 75%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-nhciao-post.webp" alt="Screenshot of a Reddit post by u/nhciao demonstrating QR code generation with diffusion models" style="width: 100%; height: auto;" />
</div>

ControlNets add the ability to “control” the images made by diffusion models like Stable Diffusion or Flux using some other image. You might, for instance, use this simple line drawing of a turtle to control pose and position and size — all generations match the line drawing on those factors. This can be much more expressive than prompting! “The turtle is looking up and to the left with a look of resignation on its face, taking up the bottom two-thirds of the image…”

<div style="max-width: 33%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-controlnet-sample.webp" alt="A line drawing of a turtle is converted into images of turtles with the same structure" style="width: 100%; height: auto;" />
</div>

Separately, QR (Quick Response) codes are [designed](https://perthirtysix.com/how-the-heck-do-qr-codes-work) to transmit short snippets of information between machines, just like other protocols you may be more familiar with (HTTP/IP/Ethernet). But they transmit via a chaotic and unpredictable medium: bright and dark patches of color that modulate light in open air, at human scales, and without the protective shielding of a fiber optic cable. And because QR code readers have to be robust to interference in that medium, like [the piece of paper they are printed on being torn](https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/QR_Code_Damaged.jpg/1200px-QR_Code_Damaged.jpg), the QR code protocol comes with sophisticated error correction.

The insight from nhciao was that ControlNets based on brightness patterns or edges, like the one demonstrated above, could be used to produce images with the brightness and darkness patterns of a QR code. And thanks to the error correction, the model can exercise a bit of creative license and “corrupt” the pattern to better match the prompt while still communicating the encoded message.

Like many others, some of us jumped on these “QArt codes” immediately — all the way back in the summer of 2023.

<div style="max-width: 33%; margin: 0 auto;">
  <a href="https://x.com/charles_irl/status/1669842036860788736">
    <img src="https://modal-cdn.com/blog/images/qart-codes-launch-2023.webp" alt="https://x.com/charles_irl/status/1669842036860788736" style="width: 100%; height: auto;" />
  </a>
</div>

## Then comes the disappointment, like QR codes that don’t scan.

So much for the party, now for the hangover. The problem that came next, and the reason you haven’t seen gorgeous QR codes replace the standard black-and-white squares, was the same problem that bedevils demos of coding agents and artificial lawyers and self-driving cars — “it worked on my ~~machine~~ prompt”. It’s hard to consistently create QR codes that are both gorgeous and scannable!

Consider, for instance, the image below, which we generated using a web app created by nhciao. This image may look a bit like a QR code, especially if you squint, but we haven’t been able to get it to scan. The model’s attempt to build the required Finder Pattern (concentric squares of alternating black and white) in the bottom-left out of a dark skyscraper and some reflections appears to have failed.

<div style="max-width: 25%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-sample-failure.webp" alt="A city skyline with fireworks with some elements of a QR code included" style="width: 100%; height: auto;" />
  <small>Not quite a QR code!</small>
</div>

This is a show-stopping bug. A putative QR code that readers can’t scan isn’t a QR code, it’s just a picture with a weird aesthetic. Similarly, failures for coding agents that neglect to implement features or chatbots that offer off-policy refunds limit their applicability.

So in building the initial version of [qart.codes](https://qart.codes), we focused first and foremost on this problem — “scannability”.

The result was a system that produced scannable QR codes with a reasonable probability (as in, it didn’t make us want to tear our hair out), so long as we only prompted with textures or styles, like “computer circuitry, splashes of color in gunmetal gray”, and not with complex scenes, like “a patient orangutan explains string theory to an anime waifu”.

We started using it in a few places where we were previously using QR codes — and even in places where we weren’t using QR codes previously because they’d ruin the vibe.

<div style="width: 50%; margin: 0 auto;">
  <a href="https://www.youtube.com/watch?v=N7lJY5IKVLE&t=2364s">
    <img src="https://modal-cdn.com/blog/images/qart-codes-sample-usage-irl.webp" alt="A slide showing a link displayed via a QR code" style="width: 100%; height: auto;" />
  </a>
  <small>A QArt code in the slides for a talk by one of the authors.</small>
</div>

With some creativity and effort on post-processing, you could even achieve some pretty cool effects!

<div style="width: 50%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-sample-composite.webp" alt="A QArt code created by superimposing an image (the logo for Lovers in a Dangerous Spacetime) over a generated QArt code." style="width: 100%; height: auto;" />
  <small>A QArt code created by superimposing an image (the logo for Lovers in a Dangerous Spacetime) over a generated QArt code.</small>
</div>

But it was far from the promise of the original demo.

## We solved this quality gap by developing good evals, following the standard ML engineering playbook: collect human judgments, align to them, then scale.

The problem here is the problem of _evaluation_ — determining the value or quality of the system. In traditional software, most evaluation can be done objectively. It can even be done “rationally” (as opposed to empirically). That is, you only need a single demonstration or logical argument for correctness or incorrectness. Think of simple repros and compiler guarantees.

But neural networks are less like the digital computers we are used to programming and more like analog computers. They are a sloppy heap of floating point numbers, not an elegant stack of integers. Correctness and quality are measured and defined for a specific use case and up to a tolerance — if they are measured and defined at all!

The tools we use to assess quality for these systems are called _evals_. They combine a procedure for producing inputs (which might just be a database or files!) with a procedure for evaluating outputs (which might be human labelers or might be a computer program). To engineer these procedures, you need to understand the goals of your system.

Our system has two core goals:

1. produce an image that a QR reader can scan
2. produce an aesthetically appealing image.

One servant cannot serve two masters, so we needed to determine how to trade off between these goals.

Aesthetic quality is

- primarily the domain of the underlying foundation models,
- highly subjective and so variable across users, and
- difficult to measure well.

Scanning, on the other hand, is

- firmly in our application domain and maps onto correctness,
- has minimal variability across users, and
- easy to measure objectively.

So we decided to make scan rate the key target for eval development.

Next, the goals need to be operationalized, mapped onto concrete processes and measurements.

We first operationalized our two goals as “can be scanned by a human wielding an iPhone pointed at a screen in our office” and “gets a thumbs up from the prompter”.

These both involve a lot of human labor, so we next came up with automated processes to replace them. We found the [QReader library](https://github.com/Eric-Canas/qreader) for QR code scanning, which uses a YOLO model to detect QR codes and then applies a number of transformations, like blurring and thresholding, before attempting to interpret the image as a code. We also found a simple aesthetic rating predictor from the Stable Diffusion community — a quick-and-dirty machine learning model that could predict human aesthetic ratings.

But those systems are also heuristic and might themselves make mistakes we can’t predict. So we needed to be sure they were aligned with our trusted human process, and we couldn’t just rely on tests and logic. We needed to run experiments to know that they were good.

We needed evals for our evals.

We built our evals iteratively. We vibe-checked them manually at first and then with results on 100 prompt-URL pairs (first image below). Finally, we scaled up our alignment check for our evals to results on about two thousand prompt-URL pairs.

That meant we needed to attempt to scan thousands of QR codes by hand while writing down the results and our aesthetic judgment. Sometimes, as an engineer, you’ve just go to roll your sleeves up and do some manual labor. Major props to Will Shainin on the team for taking the plunge (it’s always the mechanical/electrical engineers, not the PhDs).

<div style="display: flex; flex-direction: column; justify-content: center; margin: 0 auto; max-width: 50%;">
  <div style="display: flex; gap: 10px; width: 100%;">
    <div style="flex: 1; display: flex; flex-direction: column; gap: 10px;">
      <img src="https://modal-cdn.com/blog/images/qart-codes-evals-apparatus.webp" alt="A photo of a post-it note attached to a computer monitor indicating four options: scans/not scans, good/not good. The computer monitor shows a simple notebook interface for evaluating QArt codes." style="width: 100%; height: auto;" />
      <img src="https://modal-cdn.com/blog/images/qart-codes-charles-dunteman-evals.webp" alt="Two of the authors manually check whether a QArt code scans." style="width: 100%; height: auto;" />
    </div>
    <div style="flex: 1;">
      <img src="https://modal-cdn.com/blog/images/qart-codes-evals-at-home.webp" alt="A screenshot of a mobile phone displaying a link decoded from a QArt code." style="width: 100%; height: auto;" />
    </div>
  </div>
<small>You may not like it, but this is what peak ML engineering performance looks like.</small>
</div>

As you can see, the “apparatus” here can be pretty low-tech and low-effort. Tools of the trade include post-it notes, whiteboards, spreadsheets, and Jupyter notebooks — in roughly that order! Sticking to simple techniques keeps the focus where it belongs: on the data and the problem.

One piece where we did find it helpful to use an external tool was experiment management and data visualization, which crosses from ML software to data visualization to team coordination.

We used [Weights & Biases’ Weave](https://github.com/wandb/weave) for this, since one of our team members had some experience with it (conflict of interest note: [he is now fully divested](https://x.com/charles_irl/status/1925569091781448004)). We were able to log raw data from our experiments to \`wandb\` and then construct structured charts and analyses on the fly, all shareable across the team.

![A screenshot of the Weave user interface showing sample QArt codes and derived metrics.](https://modal-cdn.com/blog/images/qart-codes-weave-plot.webp)
<small>
An example W&B Weave chart grouping generations by the system version (v1/v2) and whether they scanned (True/False) and displaying samples along with a distribution of aesthetic scores.
</small>

FYI: while the details of the approach for this project are idiosyncratic, the approach itself is not at all! See, for instance, Hamel Husain’s blog post [“Creating a LLM-as-a-Judge That Drives Business Results”](https://hamel.dev/blog/posts/llm-judge/).

## The final piece (not the first) is scaling up offline compute to select system parameters.

Putting it all together, our final engineering goal was to

- achieve a ninety-five percent scan rate, as measured by QReader, and
- not regress on aesthetic quality, as measured by the aesthetic rating predictor

on a set of prompts and URLs.

We manually iterated on code, checking evals ad hoc as we went, until we’d narrowed down the outlines of our system. We developed new prompting strategies, confirmed our model choice, and determined which parameters we needed to vary and over which ranges (tl;dr - long prompts, stick with SD1.5 for now, and focus on ControlNet start time).

This part is still pretty vibes-based, and it’s where the great ML engineers, the ones who can 10x a project and _avoid_ a million dollar training run, are separated from the merely good.

<div style="max-width: 75%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-ml-vibe-engineering.webp" alt="Two photographs, juxtaposed: one of the authors evaluating QArt codes manually, his pose matching that of the man in the other photograph. That man is Rick Rubin, intently producing music." style="width: 100%; height: auto;" />
  <small>Yeah man, we need the guidance to come in on the track a bit earlier — and can somebody turn down the diffusion noise?</small>
</div>

Once we were ready to sweep over key configuration parameters, it was time to scale up. Thanks to our trusty evals, we didn’t need ten engineer-seconds per image anymore, just a computer-second or two. So we could scale this up into the tens of thousands of images and calculate our figures of merit in minutes. (BTW [Modal’s serverless platform](/) makes this trivial, just a few lines of code).

But even though we had built an eval system we trusted, we wanted to continue to look at the data to check whether our evals still aligned with our heuristic judgments.

For this, we developed a visualization we called the “toast plot”, after a famous bit of Internet culture.

<div style="max-width: 50%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-toast-plot.webp" alt="A grid of pieces of toast, arranged in rows by the amount of time they were toasted and arranged in columns by the temperature they were toasted at." style="width: 100%; height: auto;" />
  <small>POV: you are an ML engineer making breakfast.</small>
</div>

Two parameters of interest vary along two axes — how long is the bread cooked for & at what temperature; how long is the ControlNet guidance in place & at what strength. The results for a single case are below.

<div style="max-width: 50%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-codes-toast-plot-sample.webp" alt="A grid of QArt codes, arranged in rows by the amount of time they were subjected to ControlNet guidance and arranged in columns by the strength of the ControlNet guidance." style="width: 100%; height: auto;" />
  <small>An instance of the “toast plot” for one prompt.</small>
</div>

We selected the configuration one row and one column from the top-left corner, which produced images that had much better aesthetics than the existing system.

But it didn’t hit our objective of ninety-five percent scan rate — in fact, it actually had a lower scan rate than our existing systems.

But we hadn’t given up on our goals. We just used another technique: _inference-time compute scaling_.

## Our evals were good enough to move them to production — so we could solve all of our problems by scaling compute!

Let’s step back for a second. Our evals are how we measure our system’s performance offline. We automated them, so now they are fast. Why not run our evals in production so that we can improve our system’s performance _online_?

The easiest move is to create multiple outputs in parallel and then compute evaluation metrics on all of them. These can either be used on the backend (e.g. to retry) or delivered to the frontend. We chose the latter. Our frontend then ranks the QR codes — first by whether they scan, then by their aesthetic score — and selects the top four for display.

Scaling up parallel generations maps rather nicely onto the hardware used for inference: GPUs. The [one thing every engineer needs to know about GPUs](https://www.youtube.com/watch?v=ch2ODgbJjlA) is that they are designed to achieve high throughput through massive concurrency and parallelism.

Producing multiple images for a single prompt exposes more parallelism for the GPU to exploit. In this case, we get exponential improvement in scan probability (\`p^n\`) for sublinear latency cost. That’s what engineers call “a big win”. For a walkthrough of this same basic idea applied to LLMs, see [our blog post on the “Large Language Monkeys” paper](/blog/llama-human-eval).

The usual blocker is that even once automated, the evals are too slow to run in production. Even though our evals do require running neural networks, these networks are much lighter weight than the generator itself and so contribute far less to latency.

By creating eight generations per request, we were able to hit our ninety-five percent scan rate SLO (measured per batch) while staying within an acceptable latency (at time of writing, under 20s p95 end-to-end) while improving aesthetic quality (just look at them!).

<div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; max-width: 50%; margin: 0 auto;">
  <img src="https://modal-cdn.com/blog/images/qart-code-mondrian.webp" alt="A QArt code in the style of Piet Mondrian." style="width: 100%; height: auto;" />
  <img src="https://modal-cdn.com/blog/images/qart-code-floral.webp" alt="A QArt code displaying a bouquet of flowers." style="width: 100%; height: auto;" />
  <img src="https://modal-cdn.com/blog/images/qart-code-mushrooms.webp" alt="A QArt code depicting a fantastical mushroom forest." style="width: 100%; height: auto;" />
  <img src="https://modal-cdn.com/blog/images/qart-code-industrial.webp" alt="A QArt code showing a grim, dark industrial scene." style="width: 100%; height: auto;" />
</div>

You can try the service for yourself by clicking this link: [https://qart.codes](https://qart.codes) — or just scan one of the codes above.

## If you’d like to go “beyond the demo” and build robust applications of generative models, try Modal.

The present of generative models and artificial intelligence is hype and vaporware that promises the stars but is at best just a start.

We expect this technology’s future, and perhaps a noticeable percentage of the future world economy, to look rather different: taking hard problems and constructing automated evaluations for them. Building hills for engineers and their machines to climb. For more on this vision, see the work of [Andon Labs](https://andonlabs.com/), who partnered with Anthropic on [Claude Vend](https://www.anthropic.com/research/project-vend-1).

If you’re interested in building that future, we think Modal, the serverless platform we are building and which we used to do this work, is a great tool. It provides high-performance, flexible compute that can scale up your evals and your inference with a Python SDK loved by ML researchers and production engineers alike. Check out [our marketing site](/) for details.

_The authors would like to thank [u/nhciao](https://reddit.com/u/nhciao) for sharing the initial QArt codes work, [Illyasviel](https://huggingface.co/lllyasviel/ControlNet) and [monster-labs](https://huggingface.co/monster-labs) for training useful ControlNets for QArt code generation, and [Axel Setyanto](https://www.linkedin.com/in/axelsetyanto/) & Teddy Frye for work on the frontend._

_We’d also like to thank the following reviewers: Colin Weld & Peyton Walters of Modal and [Hamel Husain](https://twitter.com/hamelhusain) (the [evals guy](https://bit.ly/evals-ai))._
`,meta:{description:`There's only one playbook for improving generative applications. Read about it here.`}},{title:m,description:h,authors:g,date:_,length:v,category:y,published:b,layout:x,toc:S,rawContent:C,meta:w}=p,T=t(`<p>Two techniques dominate discussion of the engineering of language model applications and artificial intelligence: <!> and <!>. These techniques are general, far beyond topics du jour like RAG chatbots and code completion and AI boyfriends. In fact, they are fundamental to any application of foundation generative models.</p> <p>In this blog post, we’ll walk through how we used evals and inference-time scaling to improve the quality for our implementation of one of the first viral applications of image generation models: encoding QR data inside a generated image (aka <em>QArt codes</em>).</p> <p>Here are some samples from our system, without any per-prompt cherry-picking:</p> <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; max-width: 50%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-code-green-cubes.webp" alt="Neon green cubes, rendered in blender…"/> <img src="https://modal-cdn.com/blog/images/qart-code-jungle.webp" alt="A dense jungle scene filled with towering trees, intertwining vines, and an abundance of foliage…"/> <img src="https://modal-cdn.com/blog/images/qart-code-penguins.webp" alt="Penguins have a picnic on the Savannah…"/> <img src="https://modal-cdn.com/blog/images/qart-code-graffiti.webp" alt="A close-up view of a vibrant graffiti-covered urban wall…"/></div> <p>We were able to</p> <ul><li><strong>boost QR code scan rate</strong> to our <strong>service-level objective of ninety-five percent</strong></li> <li>while <strong>improving aesthetic quality</strong></li> <li>and returning codes to users <strong>in under 20s</strong>, p95.</li></ul> <p>We use codes like these in all the places we might use QR codes — like guerrilla marketing and credit giveaways.</p> <p>You can try the system for yourself at <!>, check out the code <!>, or read on for more about how we did it — and learn some ideas for engineering your own generative model applications.</p> <h2 id="generative-models-always-start-with-a-cool-demo-like-qr-codes-that-look-beautiful">Generative models always start with a cool demo, like QR codes that look beautiful.</h2> <p>The same basic story has played itself out over and over again in this early era of “generative AI”. A new foundation model or technique for some domain trends on social media and there’s a gold rush as a million hackers simultaneously build zero-to-one proofs of concept in a day. Whether it’s making pictures of cats or booking a flight, it works well enough to cut a demo video and maybe snag some of the least intelligent VC money.</p> <p>One of the first instances of this pattern kicked off on June 5, 2023, when Reddit user nhciao <!> “ControlNet for QR Code” on the Stable Diffusion subreddit, demonstrating that diffusion models with ControlNet steering could create images that were also QR codes.</p> <div style="max-width: 75%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-nhciao-post.webp" alt="Screenshot of a Reddit post by u/nhciao demonstrating QR code generation with diffusion models" style="width: 100%; height: auto;"/></div> <p>ControlNets add the ability to “control” the images made by diffusion models like Stable Diffusion or Flux using some other image. You might, for instance, use this simple line drawing of a turtle to control pose and position and size — all generations match the line drawing on those factors. This can be much more expressive than prompting! “The turtle is looking up and to the left with a look of resignation on its face, taking up the bottom two-thirds of the image…”</p> <div style="max-width: 33%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-controlnet-sample.webp" alt="A line drawing of a turtle is converted into images of turtles with the same structure" style="width: 100%; height: auto;"/></div> <p>Separately, QR (Quick Response) codes are <!> to transmit short snippets of information between machines, just like other protocols you may be more familiar with (HTTP/IP/Ethernet). But they transmit via a chaotic and unpredictable medium: bright and dark patches of color that modulate light in open air, at human scales, and without the protective shielding of a fiber optic cable. And because QR code readers have to be robust to interference in that medium, like <!>, the QR code protocol comes with sophisticated error correction.</p> <p>The insight from nhciao was that ControlNets based on brightness patterns or edges, like the one demonstrated above, could be used to produce images with the brightness and darkness patterns of a QR code. And thanks to the error correction, the model can exercise a bit of creative license and “corrupt” the pattern to better match the prompt while still communicating the encoded message.</p> <p>Like many others, some of us jumped on these “QArt codes” immediately — all the way back in the summer of 2023.</p> <div style="max-width: 33%; margin: 0 auto;"><a href="https://x.com/charles_irl/status/1669842036860788736"><img src="https://modal-cdn.com/blog/images/qart-codes-launch-2023.webp" alt="https://x.com/charles_irl/status/1669842036860788736" style="width: 100%; height: auto;"/></a></div> <h2 id="then-comes-the-disappointment-like-qr-codes-that-dont-scan">Then comes the disappointment, like QR codes that don’t scan.</h2> <p>So much for the party, now for the hangover. The problem that came next, and the reason you haven’t seen gorgeous QR codes replace the standard black-and-white squares, was the same problem that bedevils demos of coding agents and artificial lawyers and self-driving cars — “it worked on my <del>machine</del> prompt”. It’s hard to consistently create QR codes that are both gorgeous and scannable!</p> <p>Consider, for instance, the image below, which we generated using a web app created by nhciao. This image may look a bit like a QR code, especially if you squint, but we haven’t been able to get it to scan. The model’s attempt to build the required Finder Pattern (concentric squares of alternating black and white) in the bottom-left out of a dark skyscraper and some reflections appears to have failed.</p> <div style="max-width: 25%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-sample-failure.webp" alt="A city skyline with fireworks with some elements of a QR code included" style="width: 100%; height: auto;"/> <small>Not quite a QR code!</small></div> <p>This is a show-stopping bug. A putative QR code that readers can’t scan isn’t a QR code, it’s just a picture with a weird aesthetic. Similarly, failures for coding agents that neglect to implement features or chatbots that offer off-policy refunds limit their applicability.</p> <p>So in building the initial version of <!>, we focused first and foremost on this problem — “scannability”.</p> <p>The result was a system that produced scannable QR codes with a reasonable probability (as in, it didn’t make us want to tear our hair out), so long as we only prompted with textures or styles, like “computer circuitry, splashes of color in gunmetal gray”, and not with complex scenes, like “a patient orangutan explains string theory to an anime waifu”.</p> <p>We started using it in a few places where we were previously using QR codes — and even in places where we weren’t using QR codes previously because they’d ruin the vibe.</p> <div style="width: 50%; margin: 0 auto;"><a href="https://www.youtube.com/watch?v=N7lJY5IKVLE&amp;t=2364s"><img src="https://modal-cdn.com/blog/images/qart-codes-sample-usage-irl.webp" alt="A slide showing a link displayed via a QR code" style="width: 100%; height: auto;"/></a> <small>A QArt code in the slides for a talk by one of the authors.</small></div> <p>With some creativity and effort on post-processing, you could even achieve some pretty cool effects!</p> <div style="width: 50%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-sample-composite.webp" alt="A QArt code created by superimposing an image (the logo for Lovers in a Dangerous Spacetime) over a generated QArt code." style="width: 100%; height: auto;"/> <small>A QArt code created by superimposing an image (the logo for Lovers in a Dangerous Spacetime) over a generated QArt code.</small></div> <p>But it was far from the promise of the original demo.</p> <h2 id="we-solved-this-quality-gap-by-developing-good-evals-following-the-standard-ml-engineering-playbook-collect-human-judgments-align-to-them-then-scale">We solved this quality gap by developing good evals, following the standard ML engineering playbook: collect human judgments, align to them, then scale.</h2> <p>The problem here is the problem of <em>evaluation</em> — determining the value or quality of the system. In traditional software, most evaluation can be done objectively. It can even be done “rationally” (as opposed to empirically). That is, you only need a single demonstration or logical argument for correctness or incorrectness. Think of simple repros and compiler guarantees.</p> <p>But neural networks are less like the digital computers we are used to programming and more like analog computers. They are a sloppy heap of floating point numbers, not an elegant stack of integers. Correctness and quality are measured and defined for a specific use case and up to a tolerance — if they are measured and defined at all!</p> <p>The tools we use to assess quality for these systems are called <em>evals</em>. They combine a procedure for producing inputs (which might just be a database or files!) with a procedure for evaluating outputs (which might be human labelers or might be a computer program). To engineer these procedures, you need to understand the goals of your system.</p> <p>Our system has two core goals:</p> <ol><li>produce an image that a QR reader can scan</li> <li>produce an aesthetically appealing image.</li></ol> <p>One servant cannot serve two masters, so we needed to determine how to trade off between these goals.</p> <p>Aesthetic quality is</p> <ul><li>primarily the domain of the underlying foundation models,</li> <li>highly subjective and so variable across users, and</li> <li>difficult to measure well.</li></ul> <p>Scanning, on the other hand, is</p> <ul><li>firmly in our application domain and maps onto correctness,</li> <li>has minimal variability across users, and</li> <li>easy to measure objectively.</li></ul> <p>So we decided to make scan rate the key target for eval development.</p> <p>Next, the goals need to be operationalized, mapped onto concrete processes and measurements.</p> <p>We first operationalized our two goals as “can be scanned by a human wielding an iPhone pointed at a screen in our office” and “gets a thumbs up from the prompter”.</p> <p>These both involve a lot of human labor, so we next came up with automated processes to replace them. We found the <!> for QR code scanning, which uses a YOLO model to detect QR codes and then applies a number of transformations, like blurring and thresholding, before attempting to interpret the image as a code. We also found a simple aesthetic rating predictor from the Stable Diffusion community — a quick-and-dirty machine learning model that could predict human aesthetic ratings.</p> <p>But those systems are also heuristic and might themselves make mistakes we can’t predict. So we needed to be sure they were aligned with our trusted human process, and we couldn’t just rely on tests and logic. We needed to run experiments to know that they were good.</p> <p>We needed evals for our evals.</p> <p>We built our evals iteratively. We vibe-checked them manually at first and then with results on 100 prompt-URL pairs (first image below). Finally, we scaled up our alignment check for our evals to results on about two thousand prompt-URL pairs.</p> <p>That meant we needed to attempt to scan thousands of QR codes by hand while writing down the results and our aesthetic judgment. Sometimes, as an engineer, you’ve just go to roll your sleeves up and do some manual labor. Major props to Will Shainin on the team for taking the plunge (it’s always the mechanical/electrical engineers, not the PhDs).</p> <div style="display: flex; flex-direction: column; justify-content: center; margin: 0 auto; max-width: 50%;"><div style="display: flex; gap: 10px; width: 100%;"><div style="flex: 1; display: flex; flex-direction: column; gap: 10px;"><img src="https://modal-cdn.com/blog/images/qart-codes-evals-apparatus.webp" alt="A photo of a post-it note attached to a computer monitor indicating four options: scans/not scans, good/not good. The computer monitor shows a simple notebook interface for evaluating QArt codes." style="width: 100%; height: auto;"/> <img src="https://modal-cdn.com/blog/images/qart-codes-charles-dunteman-evals.webp" alt="Two of the authors manually check whether a QArt code scans." style="width: 100%; height: auto;"/></div> <div style="flex: 1;"><img src="https://modal-cdn.com/blog/images/qart-codes-evals-at-home.webp" alt="A screenshot of a mobile phone displaying a link decoded from a QArt code." style="width: 100%; height: auto;"/></div></div> <small>You may not like it, but this is what peak ML engineering performance looks like.</small></div> <p>As you can see, the “apparatus” here can be pretty low-tech and low-effort. Tools of the trade include post-it notes, whiteboards, spreadsheets, and Jupyter notebooks — in roughly that order! Sticking to simple techniques keeps the focus where it belongs: on the data and the problem.</p> <p>One piece where we did find it helpful to use an external tool was experiment management and data visualization, which crosses from ML software to data visualization to team coordination.</p> <p>We used <!> for this, since one of our team members had some experience with it (conflict of interest note: <!>). We were able to log raw data from our experiments to <code>wandb</code> and then construct structured charts and analyses on the fly, all shareable across the team.</p> <p><!></p> <small>An example W&B Weave chart grouping generations by the system version (v1/v2) and whether they scanned (True/False) and displaying samples along with a distribution of aesthetic scores.</small> <p>FYI: while the details of the approach for this project are idiosyncratic, the approach itself is not at all! See, for instance, Hamel Husain’s blog post <!>.</p> <h2 id="the-final-piece-not-the-first-is-scaling-up-offline-compute-to-select-system-parameters">The final piece (not the first) is scaling up offline compute to select system parameters.</h2> <p>Putting it all together, our final engineering goal was to</p> <ul><li>achieve a ninety-five percent scan rate, as measured by QReader, and</li> <li>not regress on aesthetic quality, as measured by the aesthetic rating predictor</li></ul> <p>on a set of prompts and URLs.</p> <p>We manually iterated on code, checking evals ad hoc as we went, until we’d narrowed down the outlines of our system. We developed new prompting strategies, confirmed our model choice, and determined which parameters we needed to vary and over which ranges (tl;dr - long prompts, stick with SD1.5 for now, and focus on ControlNet start time).</p> <p>This part is still pretty vibes-based, and it’s where the great ML engineers, the ones who can 10x a project and <em>avoid</em> a million dollar training run, are separated from the merely good.</p> <div style="max-width: 75%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-ml-vibe-engineering.webp" alt="Two photographs, juxtaposed: one of the authors evaluating QArt codes manually, his pose matching that of the man in the other photograph. That man is Rick Rubin, intently producing music." style="width: 100%; height: auto;"/> <small>Yeah man, we need the guidance to come in on the track a bit earlier — and can somebody turn down the diffusion noise?</small></div> <p>Once we were ready to sweep over key configuration parameters, it was time to scale up. Thanks to our trusty evals, we didn’t need ten engineer-seconds per image anymore, just a computer-second or two. So we could scale this up into the tens of thousands of images and calculate our figures of merit in minutes. (BTW <!> makes this trivial, just a few lines of code).</p> <p>But even though we had built an eval system we trusted, we wanted to continue to look at the data to check whether our evals still aligned with our heuristic judgments.</p> <p>For this, we developed a visualization we called the “toast plot”, after a famous bit of Internet culture.</p> <div style="max-width: 50%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-toast-plot.webp" alt="A grid of pieces of toast, arranged in rows by the amount of time they were toasted and arranged in columns by the temperature they were toasted at." style="width: 100%; height: auto;"/> <small>POV: you are an ML engineer making breakfast.</small></div> <p>Two parameters of interest vary along two axes — how long is the bread cooked for & at what temperature; how long is the ControlNet guidance in place & at what strength. The results for a single case are below.</p> <div style="max-width: 50%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-codes-toast-plot-sample.webp" alt="A grid of QArt codes, arranged in rows by the amount of time they were subjected to ControlNet guidance and arranged in columns by the strength of the ControlNet guidance." style="width: 100%; height: auto;"/> <small>An instance of the “toast plot” for one prompt.</small></div> <p>We selected the configuration one row and one column from the top-left corner, which produced images that had much better aesthetics than the existing system.</p> <p>But it didn’t hit our objective of ninety-five percent scan rate — in fact, it actually had a lower scan rate than our existing systems.</p> <p>But we hadn’t given up on our goals. We just used another technique: <em>inference-time compute scaling</em>.</p> <h2 id="our-evals-were-good-enough-to-move-them-to-production--so-we-could-solve-all-of-our-problems-by-scaling-compute">Our evals were good enough to move them to production — so we could solve all of our problems by scaling compute!</h2> <p>Let’s step back for a second. Our evals are how we measure our system’s performance offline. We automated them, so now they are fast. Why not run our evals in production so that we can improve our system’s performance <em>online</em>?</p> <p>The easiest move is to create multiple outputs in parallel and then compute evaluation metrics on all of them. These can either be used on the backend (e.g. to retry) or delivered to the frontend. We chose the latter. Our frontend then ranks the QR codes — first by whether they scan, then by their aesthetic score — and selects the top four for display.</p> <p>Scaling up parallel generations maps rather nicely onto the hardware used for inference: GPUs. The <!> is that they are designed to achieve high throughput through massive concurrency and parallelism.</p> <p>Producing multiple images for a single prompt exposes more parallelism for the GPU to exploit. In this case, we get exponential improvement in scan probability (<code>p^n</code>) for sublinear latency cost. That’s what engineers call “a big win”. For a walkthrough of this same basic idea applied to LLMs, see <!>.</p> <p>The usual blocker is that even once automated, the evals are too slow to run in production. Even though our evals do require running neural networks, these networks are much lighter weight than the generator itself and so contribute far less to latency.</p> <p>By creating eight generations per request, we were able to hit our ninety-five percent scan rate SLO (measured per batch) while staying within an acceptable latency (at time of writing, under 20s p95 end-to-end) while improving aesthetic quality (just look at them!).</p> <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; max-width: 50%; margin: 0 auto;"><img src="https://modal-cdn.com/blog/images/qart-code-mondrian.webp" alt="A QArt code in the style of Piet Mondrian." style="width: 100%; height: auto;"/> <img src="https://modal-cdn.com/blog/images/qart-code-floral.webp" alt="A QArt code displaying a bouquet of flowers." style="width: 100%; height: auto;"/> <img src="https://modal-cdn.com/blog/images/qart-code-mushrooms.webp" alt="A QArt code depicting a fantastical mushroom forest." style="width: 100%; height: auto;"/> <img src="https://modal-cdn.com/blog/images/qart-code-industrial.webp" alt="A QArt code showing a grim, dark industrial scene." style="width: 100%; height: auto;"/></div> <p>You can try the service for yourself by clicking this link: <!> — or just scan one of the codes above.</p> <h2 id="if-youd-like-to-go-beyond-the-demo-and-build-robust-applications-of-generative-models-try-modal">If you’d like to go “beyond the demo” and build robust applications of generative models, try Modal.</h2> <p>The present of generative models and artificial intelligence is hype and vaporware that promises the stars but is at best just a start.</p> <p>We expect this technology’s future, and perhaps a noticeable percentage of the future world economy, to look rather different: taking hard problems and constructing automated evaluations for them. Building hills for engineers and their machines to climb. For more on this vision, see the work of <!>, who partnered with Anthropic on <!>.</p> <p>If you’re interested in building that future, we think Modal, the serverless platform we are building and which we used to do this work, is a great tool. It provides high-performance, flexible compute that can scale up your evals and your inference with a Python SDK loved by ML researchers and production engineers alike. Check out <!> for details.</p> <p><em>The authors would like to thank <!> for sharing the initial QArt codes work, <!> and <!> for training useful ControlNets for QArt code generation, and <!> & Teddy Frye for work on the frontend.</em></p> <p><em>We’d also like to thank the following reviewers: Colin Weld & Peyton Walters of Modal and <!> (the <!>).</em></p>`,1);function E(t,m){let h=a(m,[`children`,`$$slots`,`$$events`,`$$legacy`]);f(t,o(()=>h,()=>p,{children:(t,a)=>{var o=T(),f=s(o),p=c(e(f));d(p,{href:`https://x.com/leonardtang_/status/1919147635794977207`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`evals`))},$$slots:{default:!0}}),d(c(p,2),{href:`/blog/llama-human-eval`,children:(e,t)=>{l(),i(e,r(`inference-time compute scaling`))},$$slots:{default:!0}}),l(),n(f);var m=c(f,14),h=c(e(m));d(h,{href:`https://qart.codes`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`https://qart.codes`))},$$slots:{default:!0}}),d(c(h,2),{href:`https://github.com/charlesfrye/qart-codes`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`here`))},$$slots:{default:!0}}),l(),n(m);var g=c(m,6);d(c(e(g)),{href:`https://reddit.com/r/StableDiffusion/comments/141hg9x/controlnet_for_qr_code/`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`posted`))},$$slots:{default:!0}}),l(),n(g);var _=c(g,8),v=c(e(_));d(v,{href:`https://perthirtysix.com/how-the-heck-do-qr-codes-work`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`designed`))},$$slots:{default:!0}}),d(c(v,2),{href:`https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/QR_Code_Damaged.jpg/1200px-QR_Code_Damaged.jpg`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`the piece of paper they are printed on being torn`))},$$slots:{default:!0}}),l(),n(_);var y=c(_,18);d(c(e(y)),{href:`https://qart.codes`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`qart.codes`))},$$slots:{default:!0}}),l(),n(y);var b=c(y,42);d(c(e(b)),{href:`https://github.com/Eric-Canas/qreader`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`QReader library`))},$$slots:{default:!0}}),l(),n(b);var x=c(b,16),S=c(e(x));d(S,{href:`https://github.com/wandb/weave`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`Weights & Biases’ Weave`))},$$slots:{default:!0}}),d(c(S,2),{href:`https://x.com/charles_irl/status/1925569091781448004`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`he is now fully divested`))},$$slots:{default:!0}}),l(3),n(x);var C=c(x,2);u(e(C),{src:`https://modal-cdn.com/blog/images/qart-codes-weave-plot.webp`,alt:`A screenshot of the Weave user interface showing sample QArt codes and derived metrics.`}),n(C);var w=c(C,4);d(c(e(w)),{href:`https://hamel.dev/blog/posts/llm-judge/`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`“Creating a LLM-as-a-Judge That Drives Business Results”`))},$$slots:{default:!0}}),l(),n(w);var E=c(w,16);d(c(e(E)),{href:`/`,children:(e,t)=>{l(),i(e,r(`Modal’s serverless platform`))},$$slots:{default:!0}}),l(),n(E);var D=c(E,24);d(c(e(D)),{href:`https://www.youtube.com/watch?v=ch2ODgbJjlA`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`one thing every engineer needs to know about GPUs`))},$$slots:{default:!0}}),l(),n(D);var O=c(D,2);d(c(e(O),3),{href:`/blog/llama-human-eval`,children:(e,t)=>{l(),i(e,r(`our blog post on the “Large Language Monkeys” paper`))},$$slots:{default:!0}}),l(),n(O);var k=c(O,8);d(c(e(k)),{href:`https://qart.codes`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`https://qart.codes`))},$$slots:{default:!0}}),l(),n(k);var A=c(k,6),j=c(e(A));d(j,{href:`https://andonlabs.com/`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`Andon Labs`))},$$slots:{default:!0}}),d(c(j,2),{href:`https://www.anthropic.com/research/project-vend-1`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`Claude Vend`))},$$slots:{default:!0}}),l(),n(A);var M=c(A,2);d(c(e(M)),{href:`/`,children:(e,t)=>{l(),i(e,r(`our marketing site`))},$$slots:{default:!0}}),l(),n(M);var N=c(M,2),P=e(N),F=c(e(P));d(F,{href:`https://reddit.com/u/nhciao`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`u/nhciao`))},$$slots:{default:!0}});var I=c(F,2);d(I,{href:`https://huggingface.co/lllyasviel/ControlNet`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`Illyasviel`))},$$slots:{default:!0}});var L=c(I,2);d(L,{href:`https://huggingface.co/monster-labs`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`monster-labs`))},$$slots:{default:!0}}),d(c(L,2),{href:`https://www.linkedin.com/in/axelsetyanto/`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`Axel Setyanto`))},$$slots:{default:!0}}),l(),n(P),n(N);var R=c(N,2),z=e(R),B=c(e(z));d(B,{href:`https://twitter.com/hamelhusain`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`Hamel Husain`))},$$slots:{default:!0}}),d(c(B,2),{href:`https://bit.ly/evals-ai`,rel:`nofollow`,children:(e,t)=>{l(),i(e,r(`evals guy`))},$$slots:{default:!0}}),l(),n(z),n(R),i(t,o)},$$slots:{default:!0}}))}export{E as default,p as metadata};
